if ($this->loading) {
    throw new LogicException('CQRS discovery is already in progress.');
}

if ($timeLimit !== null) {
    $now = hrtime();
    $elapsedSeconds = $now[0] - $startTime[0]
        - (int) ($now[1] < $startTime[1]);

    if ($elapsedSeconds >= $timeLimit) {
        $io->info("Time limit reached: $timeLimit seconds");
        break;
    }
}

if ($timeLimit !== null && (hrtime()[0] - $startTime) >= $timeLimit) {
    $io->info("Time limit reached: $timeLimit seconds");
    break;
}

$parsed = date_parse($value);
if ($parsed['warning_count'] !== 0
    || $parsed['error_count'] !== 0
    || isset($parsed['relative'])
    || $parsed['year'] === false
    || $parsed['month'] === false
    || $parsed['day'] === false
    || $parsed['hour'] === false
    || $parsed['minute'] === false
    || $parsed['second'] === false
) {
    throw new InvalidArgumentException('Expected a complete absolute timestamp.');
}
